insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('cc96f134-4a4f-4b7f-9c3f-a865aea19b01','5ee14cd8-547f-4535-ab8a-5a6d8e5574ea','ee176ff2-dc2c-435a-a5d7-9f7d4e670cd6','html','Frases para começar a conversa','<!doctype html><html lang=''en''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Module 1 · Key phrases</p><h1>Frases para começar a conversa</h1><p class=''lead''>Small talk é curto e leve: uma pergunta, um comentário, e você passa para a pauta.</p><h2>Abrir</h2><div class=''frases''><div class=''f''><b>How''s your week going?</b><span>Como está a sua semana?</span></div><div class=''f''><b>Good to see you again!</b><span>Que bom te ver de novo!</span></div><div class=''f''><b>Are you working from home today?</b><span>Você está trabalhando de casa hoje?</span></div></div><h2>Responder</h2><div class=''frases''><div class=''f''><b>Pretty good, thanks. Busy, but good.</b><span>Tudo bem, obrigada. Corrido, mas bem.</span></div><div class=''f''><b>Not bad at all. And yours?</b><span>Nada mal. E a sua?</span></div></div><h2>Passar para a pauta</h2><div class=''frases''><div class=''f''><b>Shall we get started?</b><span>Vamos começar?</span></div><div class=''f''><b>Okay, let''s dive in.</b><span>Certo, vamos ao que interessa.</span></div></div><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>“Fine, and you?” é de livro didático. Na vida real, <b>pretty good</b>, <b>not bad</b> ou <b>busy, but good</b> soam muito mais naturais.</p></div></div>@@JS@@</body></html>',null,2,'ingles',false);
insert into material_turmas(material_id,turma_id) values('cc96f134-4a4f-4b7f-9c3f-a865aea19b01','72d4f293-0090-42df-93c7-35375d9bbac8');
insert into fases(id,materia_id,titulo,ordem) values('c2e2e84a-c2d7-4acb-9640-476570a50cb2','5ee14cd8-547f-4535-ab8a-5a6d8e5574ea','Praticar',1);
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('8e3c66bd-8af4-4b9f-956d-3822b0ccc0d5','5ee14cd8-547f-4535-ab8a-5a6d8e5574ea','c2e2e84a-c2d7-4acb-9640-476570a50cb2','html','Exercício: qual soa mais natural?','<!doctype html><html lang=''en''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Module 1 · Practice</p><h1>Qual soa mais natural?</h1><p class=''lead''>Escolha o que um nativo diria numa call de trabalho.</p><div class=''q'' data-ok="Leve e natural, e devolve a pergunta." data-no="Correto, mas soa de livro. Tente outra."><p>Alguém pergunta: “How are you?”</p><button data-ok=''0''>I''m fine, thank you, and you?</button><button data-ok=''1''>Pretty good, thanks! How about you?</button><button data-ok=''0''>I am very well.</button><div class=''r''></div></div><div class=''q'' data-ok="Pergunta aberta e segura." data-no="Pessoal demais para o começo da call."><p>Para abrir a conversa com um cliente:</p><button data-ok=''1''>How''s your week going?</button><button data-ok=''0''>What did you do yesterday?</button><button data-ok=''0''>Are you happy?</button><div class=''r''></div></div><div class=''q'' data-ok="Gentil e natural." data-no="Formal demais (e reunion é reencontro)."><p>Para passar para a pauta:</p><button data-ok=''0''>Now we will begin the meeting.</button><button data-ok=''1''>Shall we get started?</button><button data-ok=''0''>Let''s start the reunion.</button><div class=''r''></div></div><div class=''desafio''><p class=''k''>Desafio</p><p>Escreva 2 perguntas de small talk e 2 respostas suas. Treine em voz alta.</p></div></div>@@JS@@</body></html>',null,3,'ingles',false);
insert into material_turmas(material_id,turma_id) values('8e3c66bd-8af4-4b9f-956d-3822b0ccc0d5','72d4f293-0090-42df-93c7-35375d9bbac8');
insert into fases(id,materia_id,titulo,ordem) values('704bf7ab-bdd8-421c-8dfe-dae27e4ed820','5ee14cd8-547f-4535-ab8a-5a6d8e5574ea','Aplicar',2);
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('1a2057c1-5a4d-40e5-90e7-ccfe3f1c939c','5ee14cd8-547f-4535-ab8a-5a6d8e5574ea','704bf7ab-bdd8-421c-8dfe-dae27e4ed820','html','Desafio: abra a próxima call','<!doctype html><html lang=''en''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Module 1 · Challenge</p><h1>Abra a próxima call</h1><ol><li>Na sua próxima call em inglês, abra com uma pergunta de small talk.</li><li>Faça um comentário e passe para a pauta com <b>Shall we get started?</b></li><li>Conte na aula como foi.</li></ol><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>Small talk não é obrigação de ser engraçado: é mostrar interesse por 1 ou 2 minutos.</p></div></div>@@JS@@</body></html>',null,4,'ingles',false);
