insert into material_turmas(material_id,turma_id) values('59b8d5ea-b495-442a-ac08-0ab00413abf6','72d4f293-0090-42df-93c7-35375d9bbac8');
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('9a3fa48b-53c8-4853-a78b-641288fa8554','74d808f3-f3eb-404f-bad6-da284924b28a','9a6df832-3b55-40c9-b684-046e91fe4dc1','html','Frases para conduzir a reunião','<!doctype html><html lang=''en''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Module 2 · Key phrases</p><h1>Frases para conduzir a reunião</h1><h2>Abrir e apresentar a pauta</h2><div class=''frases''><div class=''f''><b>Thanks everyone for joining.</b><span>Obrigada a todos por participarem.</span></div><div class=''f''><b>Let''s go through the agenda.</b><span>Vamos passar pela pauta.</span></div></div><h2>Pedir e dar atualizações</h2><div class=''frases''><div class=''f''><b>Where are we with the launch?</b><span>Em que pé estamos com o lançamento?</span></div><div class=''f''><b>We''re on track for Friday.</b><span>Estamos no prazo para sexta.</span></div><div class=''f''><b>We''re a bit behind on testing.</b><span>Estamos um pouco atrasados nos testes.</span></div></div><h2>Fechar</h2><div class=''frases''><div class=''f''><b>So, to recap…</b><span>Então, recapitulando…</span></div><div class=''f''><b>Who''s taking care of this?</b><span>Quem fica responsável por isso?</span></div><div class=''f''><b>Let''s follow up next week.</b><span>Vamos retomar na semana que vem.</span></div></div><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>“We are late” soa como se vocês tivessem chegado atrasados. Para prazo, use <b>behind schedule</b> ou <b>a bit behind</b>.</p></div></div>@@JS@@</body></html>',null,2,'ingles',false);
insert into material_turmas(material_id,turma_id) values('9a3fa48b-53c8-4853-a78b-641288fa8554','72d4f293-0090-42df-93c7-35375d9bbac8');
insert into fases(id,materia_id,titulo,ordem) values('be90465c-dc09-4e3c-8a44-b37e78795054','74d808f3-f3eb-404f-bad6-da284924b28a','Praticar',1);
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('05ad29bd-9bed-447f-a727-576523fb1d9d','74d808f3-f3eb-404f-bad6-da284924b28a','be90465c-dc09-4e3c-8a44-b37e78795054','html','Exercício: qual a melhor frase?','<!doctype html><html lang=''en''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Module 2 · Practice</p><h1>Qual a melhor frase?</h1><div class=''q'' data-ok="Direta e cordial." data-no="Soa brusco ou traduzido. Tente outra."><p>Para pedir uma atualização:</p><button data-ok=''0''>Give me the status now.</button><button data-ok=''1''>Where are we with the report?</button><button data-ok=''0''>What is the situation of the report?</button><div class=''r''></div></div><div class=''q'' data-ok="Natural e profissional." data-no="Late soa como chegar atrasado."><p>O projeto está atrasado:</p><button data-ok=''0''>We are late with the project.</button><button data-ok=''1''>We''re a bit behind schedule.</button><button data-ok=''0''>The project is delayed by us.</button><div class=''r''></div></div><div class=''q'' data-ok="Assim se pergunta quem assume a tarefa." data-no="Responsible não é substantivo em inglês."><p>Para definir responsáveis:</p><button data-ok=''1''>Who''s taking care of this?</button><button data-ok=''0''>Who is the responsible?</button><button data-ok=''0''>Who will make this?</button><div class=''r''></div></div></div>@@JS@@</body></html>',null,3,'ingles',false);
insert into material_turmas(material_id,turma_id) values('05ad29bd-9bed-447f-a727-576523fb1d9d','72d4f293-0090-42df-93c7-35375d9bbac8');
insert into fases(id,materia_id,titulo,ordem) values('6ffaff33-e850-4a5f-a661-48dbe9358c62','74d808f3-f3eb-404f-bad6-da284924b28a','Aplicar',2);
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('8bc5877d-db7b-4ec1-8fc0-49f887f696ec','74d808f3-f3eb-404f-bad6-da284924b28a','6ffaff33-e850-4a5f-a661-48dbe9358c62','html','Desafio: conduza 10 minutos de status','<!doctype html><html lang=''en''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Module 2 · Challenge</p><h1>Conduza 10 minutos de status</h1><ol><li>Escreva uma pauta real com 3 itens.</li><li>Prepare uma atualização e um bloqueio para cada item.</li><li>Na próxima aula, você conduz a reunião e a professora faz o time.</li></ol><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>Feche sempre com <b>to recap</b> + responsáveis + prazos: é o que faz a reunião parecer bem conduzida.</p></div></div>@@JS@@</body></html>',null,4,'ingles',false);
