insert into material_turmas(material_id,turma_id) values('93cec7a6-5726-415b-a2af-a158e3f3dc45','72d4f293-0090-42df-93c7-35375d9bbac8');
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('d9ee58dd-42ed-4d32-acb7-a0beed403c4b','82e2e568-de86-4097-b5b9-39aeacdc8758','2add4ca8-8373-4ffa-9c48-967cc97839c4','html','Frases para apresentar resultados','<!doctype html><html lang=''en''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Module 3 · Key phrases</p><h1>Frases para apresentar resultados</h1><h2>Conduzir</h2><div class=''frases''><div class=''f''><b>Let me walk you through the numbers.</b><span>Vou mostrar os números com vocês.</span></div><div class=''f''><b>As you can see on this slide…</b><span>Como vocês podem ver neste slide…</span></div></div><h2>Descrever tendências</h2><div class=''frases''><div class=''f''><b>Sales went up by 12%.</b><span>As vendas subiram 12%.</span></div><div class=''f''><b>Costs remained stable.</b><span>Os custos se mantiveram estáveis.</span></div><div class=''f''><b>We saw a slight drop in March.</b><span>Tivemos uma leve queda em março.</span></div></div><h2>Responder perguntas</h2><div class=''frases''><div class=''f''><b>That''s a great question.</b><span>Ótima pergunta.</span></div><div class=''f''><b>Let me get back to you on that.</b><span>Vou verificar e te dou um retorno.</span></div></div><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>Para percentuais, <b>went up by 12%</b> (subiu 12 pontos) é diferente de <b>went up to 12%</b> (chegou a 12%).</p></div></div>@@JS@@</body></html>',null,2,'ingles',false);
insert into material_turmas(material_id,turma_id) values('d9ee58dd-42ed-4d32-acb7-a0beed403c4b','72d4f293-0090-42df-93c7-35375d9bbac8');
insert into fases(id,materia_id,titulo,ordem) values('e11c4d8f-6f82-4166-bd46-a6422e09504b','82e2e568-de86-4097-b5b9-39aeacdc8758','Praticar',1);
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('1f76156c-8bda-41c3-9c6e-7a1d16bd1460','82e2e568-de86-4097-b5b9-39aeacdc8758','e11c4d8f-6f82-4166-bd46-a6422e09504b','html','Exercício: descreva o gráfico','<!doctype html><html lang=''en''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Module 3 · Practice</p><h1>Descreva o gráfico</h1><div class=''q'' data-ok="By indica a variação." data-no="To indica o ponto de chegada; in não se usa aqui."><p>As vendas foram de 100 para 112:</p><button data-ok=''1''>Sales went up by 12%.</button><button data-ok=''0''>Sales went up to 12%.</button><button data-ok=''0''>Sales grew in 12%.</button><div class=''r''></div></div><div class=''q'' data-ok="Profissional e mostra que você vai resolver." data-no="Soa inseguro. Tente outra."><p>Você não sabe a resposta agora:</p><button data-ok=''0''>I don''t know.</button><button data-ok=''1''>Let me get back to you on that.</button><button data-ok=''0''>No idea, sorry.</button><div class=''r''></div></div><div class=''q'' data-ok="Natural e conduz a audiência." data-no="Soa traduzido ou incorreto."><p>Para começar a parte dos números:</p><button data-ok=''0''>Now I will show the numbers.</button><button data-ok=''1''>Let me walk you through the numbers.</button><button data-ok=''0''>Look the numbers.</button><div class=''r''></div></div></div>@@JS@@</body></html>',null,3,'ingles',false);
insert into material_turmas(material_id,turma_id) values('1f76156c-8bda-41c3-9c6e-7a1d16bd1460','72d4f293-0090-42df-93c7-35375d9bbac8');
insert into fases(id,materia_id,titulo,ordem) values('a32050a7-3556-45b1-99a2-13df275cb906','82e2e568-de86-4097-b5b9-39aeacdc8758','Aplicar',2);
insert into materiais(id,materia_id,fase_id,tipo,titulo,conteudo_html,url,ordem,idioma,visivel_todos) values('66d9342e-1638-4ff7-a9ef-4e108a4aea83','82e2e568-de86-4097-b5b9-39aeacdc8758','a32050a7-3556-45b1-99a2-13df275cb906','html','Desafio: apresente 3 slides','<!doctype html><html lang=''en''><head><meta charset=''utf-8''><meta name=''viewport'' content=''width=device-width,initial-scale=1''>@@CSS@@</head><body><div class=''w''><p class=''k''>Module 3 · Challenge</p><h1>Apresente 3 slides</h1><ol><li>Escolha 3 slides reais do seu trabalho: contexto, números, próximos passos.</li><li>Grave 2 minutos apresentando, sem ler.</li><li>Envie na tarefa para receber feedback.</li></ol><div class=''dica''><p class=''k''>Dica Tu Prof</p><p>Uma frase por slide que diga <b>o que o número significa</b> vale mais que ler todos os números.</p></div></div>@@JS@@</body></html>',null,4,'ingles',false);
